insert into public.projects (slug, title, category, label, color, thumbnail, tagline, description, features, technologies, demo_url, problem, my_role, outcome, sort_order, is_published) values
  ('borrowit', 'BorrowIt', 'uiux', '{"id":"🎨 UI/UX Mobile","en":"🎨 UI/UX Mobile"}'::jsonb, '#6C5CE7', '/images/projects/borrowit/thumbnail.png', '{"id":"Platform Peminjaman Barang Kampus","en":"Campus Item Lending Platform"}'::jsonb, '{"id":"Desain antarmuka aplikasi mobile untuk memudahkan peminjaman barang antar mahasiswa di lingkungan kampus. Dilengkapi fitur verifikasi KTM untuk keamanan dan kepercayaan, chat real-time, sistem rating, serta pencarian barang berbasis lokasi. Didesain dengan tampilan modern dan bersih yang mengutamakan kemudahan penggunaan.","en":"Mobile app interface design to facilitate item lending among campus students. Features KTM verification for security, real-time chat, rating system, and location-based search. Designed with a modern, clean look prioritizing ease of use."}'::jsonb, '{"id":["Verifikasi KTM","Kategori Barang","Chat Real-time","Sistem Rating","Pencarian Berbasis Lokasi"],"en":["KTM Verification","Item Categories","Real-time Chat","Rating System","Location-based Search"]}'::jsonb, array['Figma', 'UI/UX Design', 'Mobile Design', 'Prototyping'], null, '{"id":"Mahasiswa Telkom University Purwokerto yang ingin meminjam atau meminjamkan barang di kampus biasanya masih mengandalkan cara informal: bertanya lewat grup WhatsApp, mulut ke mulut, atau papan pengumuman, tanpa ada cara untuk memverifikasi siapa peminjamnya atau melacak status barang yang dipinjam. Tidak ada rasa aman karena identitas peminjam tidak jelas, dan proses mencari barang yang dibutuhkan jadi lambat dan tidak terstruktur. BorrowIt dirancang untuk menjawab masalah ini lewat platform mobile yang membuat peminjaman barang antar mahasiswa jadi lebih aman, cepat, dan terpercaya.","en":"Students at Telkom University Purwokerto who want to borrow or lend items on campus usually still rely on informal channels: asking in WhatsApp groups, word of mouth, or notice boards, with no way to verify who the borrower is or to track the status of borrowed items. There is little sense of security because the borrower''s identity is unclear, and finding the items people need is slow and unstructured. BorrowIt was designed to solve this with a mobile platform that makes lending items between students safer, faster, and more trustworthy."}'::jsonb, '{"id":"UI/UX Designer: bertanggung jawab penuh dari riset pengguna, information architecture, wireframing, hingga UI design dan pengujian prototipe.","en":"UI/UX Designer: fully responsible for everything from user research, information architecture, and wireframing to UI design and prototype testing."}'::jsonb, '{"id":"Desain aplikasi yang mengubah cara mahasiswa meminjam barang dari sekadar tanya di grup chat menjadi proses yang jelas dan terpercaya: verifikasi KTM untuk keamanan, kategori barang yang mudah dijelajahi, pencarian berbasis lokasi, chat real-time antar pengguna, dan sistem rating untuk membangun kepercayaan antar mahasiswa.","en":"An app design that turns borrowing items from simply asking in a group chat into a clear and trustworthy process: student ID (KTM) verification for security, easy-to-browse item categories, location-based search, real-time chat between users, and a rating system that builds trust between students."}'::jsonb, 1, true),
  ('ekost', 'E-Kost Manager', 'web', '{"id":"🌐 Web App","en":"🌐 Web App"}'::jsonb, '#0C1B3A', '/images/projects/ekost/thumbnail.png', '{"id":"Platform Manajemen Kost dengan Denah 2.5D/3D Interaktif","en":"Boarding House Management Platform with Interactive 2.5D/3D Floor Plans"}'::jsonb, '{"id":"Platform web manajemen kost untuk pemilik dan penyewa. Pemilik mengelola kamar dan tipe kamar, mengundang penyewa lewat link undangan, lalu menempatkan penyewa ke kamar; penyewa melihat informasi kamarnya, tagihan, dan mengirim aduan. Fitur unggulan Denah Kost menampilkan bangunan dalam 2.5D, 3D, atau 2D (hijau = kosong, merah = terisi) yang berubah secara realtime, lengkap dengan editor denah otomatis. Versi awal dibangun dengan Laravel dan MySQL, lalu dimigrasikan ke React dan Supabase (Auth, Postgres dengan Row Level Security, Edge Functions, Realtime) dan di-deploy di Vercel.","en":"Boarding house management web platform for owners and tenants. Owners manage rooms and room types, invite tenants with an invitation link, and assign them to rooms; tenants see their room details and bills and submit complaints. The highlight feature, Floor Plan, shows the building in 2.5D, 3D, or 2D (green = vacant, red = occupied) with realtime updates and an automatic floor plan editor. The first version was built with Laravel and MySQL, then migrated to React and Supabase (Auth, Postgres with Row Level Security, Edge Functions, Realtime) and deployed on Vercel."}'::jsonb, '{"id":["Denah Kost 2.5D/3D Interaktif","Editor Denah Otomatis","Status Kamar Realtime","Kelola Kamar & Tipe Kamar","Undangan Penyewa via Link","Dashboard Pemilik & Penyewa","Keamanan Data per Pengguna (RLS)"],"en":["Interactive 2.5D/3D Floor Plan","Automatic Floor Plan Editor","Realtime Room Status","Room & Room Type Management","Tenant Invitation Links","Owner & Tenant Dashboards","Per-User Data Security (RLS)"]}'::jsonb, array['React', 'TypeScript', 'Vite', 'Tailwind CSS', 'Three.js', 'Supabase', 'PostgreSQL', 'Vercel'], 'https://e-kost-manager.vercel.app', '{"id":"Sistem pengelolaan kost di Purwokerto kebanyakan masih tradisional: pemilik mencatat data kamar dan penyewa secara manual, tanpa gambaran jelas kamar mana yang kosong atau sudah terisi, dan penyewa harus menemui pemilik langsung untuk urusan tagihan atau komplain. E-Kost Manager dibuat untuk membawa pengelolaan kost ke sistem yang lebih modern dan digital.","en":"Most boarding houses in Purwokerto are still managed the traditional way: owners record room and tenant data by hand, with no clear picture of which rooms are vacant or occupied, and tenants have to meet the owner in person to deal with bills or complaints. E-Kost Manager was built to bring boarding house management into a more modern, digital system."}'::jsonb, '{"id":"Project Manager sekaligus Backend Developer: memimpin koordinasi tim dari riset hingga rilis, sekaligus membangun sistem backend, yaitu database, autentikasi, keamanan data, dan API.","en":"Project Manager and Backend Developer: led team coordination from research to release, while building the backend system, namely the database, authentication, data security, and APIs."}'::jsonb, '{"id":"Platform yang membawa pengelolaan kost dari cara manual ke sistem digital: pemilik bisa memantau kondisi kamar secara visual lewat denah 2.5D/3D yang menampilkan status kosong/terisi secara real-time, sementara penyewa bisa cek tagihan dan mengajukan komplain sendiri tanpa harus datang langsung ke pemilik.","en":"A platform that moves boarding house management from manual work to a digital system: owners can monitor rooms visually through a 2.5D/3D floor plan that shows vacant/occupied status in real time, while tenants can check their bills and file complaints on their own without visiting the owner in person."}'::jsonb, 2, true),
  ('melodean', 'Melodean', 'uiux', '{"id":"🎨 UI/UX Mobile","en":"🎨 UI/UX Mobile"}'::jsonb, '#0066CC', '/images/projects/melodean/thumbnail.png', '{"id":"E-Learning Interaktif untuk Siswa","en":"Interactive E-Learning for Students"}'::jsonb, '{"id":"Desain antarmuka platform e-learning mobile yang menarik untuk siswa SMA. Menampilkan elemen gamifikasi termasuk poin, badge, dan leaderboard untuk memotivasi proses belajar. Dilengkapi manajemen jadwal, modul pembelajaran berbasis mata pelajaran, dan pemindaian absensi berbasis QR. Didesain dengan pendekatan playful namun tetap fungsional.","en":"Attractive mobile e-learning interface design for high school students. Features gamification elements including points, badges, and leaderboard to motivate learning. Includes schedule management, subject-based learning modules, and QR-based attendance scanning. Designed with a playful yet functional approach."}'::jsonb, '{"id":["Sistem Gamifikasi","Modul Pelajaran","Absensi QR","Leaderboard","Koleksi Badge"],"en":["Gamification System","Learning Modules","QR Attendance","Leaderboard","Badge Collection"]}'::jsonb, array['Figma', 'UI/UX Design', 'Mobile Design', 'Gamification'], null, '{"id":"Platform e-learning yang digunakan siswa SMA kebanyakan masih berupa daftar materi dan tugas yang monoton, tanpa elemen yang membuat siswa termotivasi untuk belajar secara konsisten. Akibatnya minat belajar mudah menurun dan absensi pun masih dilakukan secara manual. Melodean dirancang untuk mengubah pengalaman belajar digital siswa SMA jadi lebih interaktif dan menyenangkan lewat pendekatan gamifikasi, tanpa mengurangi fungsi utamanya sebagai platform belajar.","en":"The e-learning platforms high school students use are mostly still monotonous lists of materials and assignments, with nothing that motivates students to study consistently. As a result, interest in learning drops easily, and attendance is still taken manually. Melodean was designed to make high school students'' digital learning more interactive and enjoyable through gamification, without compromising its core function as a learning platform."}'::jsonb, '{"id":"UI/UX Designer sekaligus Project Manager: memimpin riset dan koordinasi tim dari awal hingga pengujian, sekaligus merancang langsung desain antarmuka dan sistem gamifikasinya.","en":"UI/UX Designer and Project Manager: led research and team coordination from the start through testing, while personally designing the interface and its gamification system."}'::jsonb, '{"id":"Desain aplikasi belajar yang menggabungkan modul pembelajaran berbasis mata pelajaran dengan sistem gamifikasi poin, badge, dan leaderboard untuk mendorong motivasi belajar siswa, dilengkapi fitur absensi lewat QR scan yang membuat proses administratif jadi lebih praktis bagi siswa dan guru.","en":"A learning app design that combines subject-based learning modules with a gamification system of points, badges, and leaderboards to motivate students, plus QR scan attendance that makes administrative tasks more practical for students and teachers."}'::jsonb, 3, true),
  ('nusantara', 'Nusantara Legacy', 'uiux', '{"id":"🎨 UI/UX Web","en":"🎨 UI/UX Web"}'::jsonb, '#0F3D3E', '/images/projects/nusantara/thumbnail.png', '{"id":"Platform Warisan Budaya Indonesia","en":"Indonesian Cultural Heritage Platform"}'::jsonb, '{"id":"Desain antarmuka platform web yang didedikasikan untuk melestarikan dan membagikan warisan budaya Indonesia. Menampilkan artikel budaya, podcast sejarah (Historiccast), circle komunitas, dan aktivitas interaktif. Pengguna dapat menjelajahi, berkontribusi, dan belajar tentang keragaman budaya Indonesia. Didesain dengan nuansa budaya yang kuat dan navigasi intuitif.","en":"Web platform interface design dedicated to preserving and sharing Indonesian cultural heritage. Features cultural articles, history podcasts (Historiccast), community circles, and interactive activities. Users can explore, contribute, and learn about Indonesia''s cultural diversity. Designed with a strong cultural feel and intuitive navigation."}'::jsonb, '{"id":["Artikel Budaya","Podcast Historiccast","Circle Komunitas","Aktivitas Interaktif","Pencarian & Eksplorasi"],"en":["Cultural Articles","Historiccast Podcast","Community Circle","Interactive Activities","Search & Exploration"]}'::jsonb, array['Figma', 'UI/UX Design', 'Web Design', 'Prototyping'], null, null, null, null, 4, true),
  ('paynow', 'PayNow', 'uiux', '{"id":"🎨 UI/UX Mobile","en":"🎨 UI/UX Mobile"}'::jsonb, '#3B3F8C', '/images/projects/paynow/thumbnail.jpg', '{"id":"Dompet Digital & Solusi Pembayaran","en":"Digital Wallet & Payment Solution"}'::jsonb, '{"id":"Desain antarmuka aplikasi dompet digital modern yang memungkinkan transfer uang cepat dan aman, pembayaran tagihan, dan pelacakan keuangan. Dilengkapi fitur top-up, transfer internasional, ringkasan keuangan, reward voucher, dan autentikasi biometrik untuk keamanan lebih baik. Didesain dengan fokus pada kepercayaan dan kemudahan transaksi.","en":"Modern digital wallet app interface design enabling fast and secure money transfers, bill payments, and financial tracking. Features top-up, international transfers, financial summaries, reward vouchers, and biometric authentication. Designed with a focus on trust and ease of transaction."}'::jsonb, '{"id":["Dompet Digital","Pembayaran Tagihan","Pelacakan Keuangan","Reward Voucher","Autentikasi Biometrik"],"en":["Digital Wallet","Bill Payment","Financial Tracking","Reward Vouchers","Biometric Authentication"]}'::jsonb, array['Figma', 'UI/UX Design', 'Mobile Design', 'FinTech'], null, null, null, null, 5, true),
  ('warasa', 'Warasa', 'web', '{"id":"🌐 Web & Mobile App","en":"🌐 Web & Mobile App"}'::jsonb, '#FF6B35', '/images/projects/warasa/thumbnail.png', '{"id":"Asisten E-Commerce Berbasis AI","en":"AI-Powered E-Commerce Assistant"}'::jsonb, '{"id":"Platform web dan mobile berbasis AI yang dirancang untuk membantu seller Shopee mengoptimalkan bisnis online mereka. Dilengkapi fitur smart product generation, kalkulator ROAS, SEO scoring, analisis kompetitor, dan tools bulk export. Dipercaya oleh 10.000+ seller online untuk meningkatkan performa toko mereka.","en":"AI-powered web and mobile platform designed to help Shopee sellers optimize their online business. Features smart product generation, ROAS calculator, SEO scoring, competitor analysis, and bulk export tools. Trusted by 10,000+ online sellers to improve their store performance."}'::jsonb, '{"id":["Generator Produk AI","Kalkulator ROAS","Optimasi SEO","Analisis Kompetitor","Ekspor Massal"],"en":["AI Product Generator","ROAS Calculator","SEO Optimization","Competitor Analysis","Bulk Export"]}'::jsonb, array['Laravel', 'Flutter', 'AI/ML', 'Shopee API', 'JavaScript'], null, null, null, null, 6, true),
  ('spr', 'Emotion-Based Music Recommender', 'data', '{"id":"📊 Data Analysis","en":"📊 Data Analysis"}'::jsonb, '#10B981', '/images/projects/spr/chart_1.png', '{"id":"Sistem Rekomendasi Musik Berbasis Emosi","en":"Emotion-Based Music Recommendation System"}'::jsonb, '{"id":"Sistem rekomendasi musik berbasis AI yang dapat dijelaskan, menggunakan attention-based emotion preference learning. Sistem mendeteksi emosi pengguna dari input teks, menerapkan TF-IDF + Logistic Regression untuk klasifikasi sentimen, menggunakan analisis fitur berbobot attention, dan memberikan rekomendasi lagu berbasis konten dengan transparansi XAI (Explainable AI) penuh.","en":"An explainable AI-based music recommendation system using attention-based emotion preference learning. The system detects user emotions from text input, applies TF-IDF + Logistic Regression for sentiment classification, uses attention-weighted feature analysis, and provides content-based song recommendations with full XAI transparency."}'::jsonb, '{"id":["Deteksi Emosi","Pembobotan Berbasis Attention","Content-Based Filtering","Explainable AI (XAI)","Klasifikasi Sentimen","Evaluasi Top-K"],"en":["Emotion Detection","Attention-Based Weighting","Content-Based Filtering","Explainable AI (XAI)","Sentiment Classification","Top-K Evaluation"]}'::jsonb, array['Python', 'Scikit-learn', 'Pandas', 'Matplotlib', 'TF-IDF', 'Logistic Regression'], null, null, null, null, 7, true),
  ('pixora', 'Pixora', 'web', '{"id":"🌐 Web & Mobile App","en":"🌐 Web & Mobile App"}'::jsonb, '#E11D48', '/images/projects/pixora/thumbnail.png', '{"id":"Platform Booking Studio Fotografi","en":"Photography Studio Booking Platform"}'::jsonb, '{"id":"Platform booking studio fotografi full-stack yang menghubungkan pelanggan dengan layanan fotografi profesional. Versi web dibangun dengan Laravel menyediakan landing page, katalog paket, kalender booking interaktif, pembayaran online via Midtrans (VA, E-Wallet, QRIS), invoice digital, admin dashboard, serta integrasi AI assistant. Versi mobile dibangun dengan Flutter menghadirkan pengalaman booking yang seamless dengan fitur browse paket, kalender ketersediaan, pembayaran dalam aplikasi, chatbot AI, Google Sign-In, dan manajemen profil lengkap dengan riwayat booking.","en":"Full-stack photography studio booking platform connecting customers with professional photography services. Web version built with Laravel provides landing page, package catalog, interactive booking calendar, online payment via Midtrans (VA, E-Wallet, QRIS), digital invoices, admin dashboard, and AI assistant integration. Mobile version built with Flutter delivers a seamless booking experience with package browsing, an availability calendar, in-app payments, an AI chatbot, Google Sign-In, and full profile management with booking history."}'::jsonb, '{"id":["Booking Online","Pembayaran Midtrans","AI Assistant","Kalender Interaktif","Admin Dashboard","Mobile App Flutter"],"en":["Online Booking","Midtrans Payment","AI Assistant","Interactive Calendar","Admin Dashboard","Flutter Mobile App"]}'::jsonb, array['Laravel', 'Flutter', 'MySQL', 'Midtrans', 'AI Integration', 'Google Auth'], null, null, null, null, 8, true),
  ('qa-cazh', 'Quality Assurance — PT Cazh', 'qa', '{"id":"🔍 Quality Assurance","en":"🔍 Quality Assurance"}'::jsonb, '#0EA5E9', '/images/projects/qa-cazh/thumbnail.png', '{"id":"Pengujian Kualitas Produk Digital","en":"Digital Product Quality Testing"}'::jsonb, '{"id":"Proyek magang sebagai Quality Assurance di PT Cazh Purwokerto (Juli — Agustus 2026). Bertanggung jawab melakukan pengujian fungsional dan non-fungsional pada produk digital perusahaan, menyusun test case dan test scenario, melaporkan bug melalui bug tracking system, serta memastikan kualitas produk sebelum rilis ke production environment.","en":"Internship project as Quality Assurance at PT Cazh Purwokerto (July — August 2026). Responsible for conducting functional and non-functional testing on digital products, preparing test cases and test scenarios, reporting bugs through bug tracking system, and ensuring product quality before release to production."}'::jsonb, '{"id":["Pengujian Fungsional","Penyusunan Test Case","Pelaporan Bug","Regression Testing","Validasi UI/UX"],"en":["Functional Testing","Test Case Design","Bug Reporting","Regression Testing","UI/UX Validation"]}'::jsonb, array['Manual Testing', 'Test Case', 'Bug Tracking', 'Functional Testing', 'Regression Testing'], null, null, null, null, 9, true);

